fields.InputDefinition:
{
  "goal": "Using the application switcher dropdown next to the logo (NOT the Ctrl+K search box), open the Communication app. Then walk these sections IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) comm-providers — open the Providers section and confirm provider cards render, each showing capability chips (e.g. Sending and Receiving with check/x marks, possibly Scheduled/Drafts/Forward/Reply), a small stats row (Sent 24h / Success % / Failed), a Status badge (Active/Disabled), and Configure/Analytics footer actions — OR a valid empty state if no providers are configured; (2) comm-monitor — open the Monitor section and confirm the monitor analytics render: a KPI strip with four cards (Total Sent, Delivery Rate %, Pending, Failed), a 'Delivery Volume' time-series chart, a 'Provider Health' list, and a 'Channel Breakdown' — each populated OR showing a valid empty state; (3) comm-runs — open the Bulk Runs (Runs) section and confirm a summary row (Active Runs, Completed 24h, Success Rate %) and a run timeline listing runs with status badges/dots (Complete/Failed/In-Progress/Pending) — OR a 'No communication runs found' empty state — then click the 'Refresh' button and confirm the view reloads and stays functional. Keep going until every section has been visited. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "comm-providers",
      "instruction": "provider cards with capabilities and 24h stats",
      "visualCriteria": [
        "Provider cards render with capability chips and a 24h stats row (Sent / Success % / Failed), each with a Status badge and Configure/Analytics footer buttons — OR a valid empty state if no providers are configured"
      ]
    },
    {
      "name": "comm-monitor",
      "instruction": "monitor analytics KPIs and charts",
      "visualCriteria": [
        "The Monitor analytics render a KPI strip of four metric cards (Total Sent, Delivery Rate %, Pending, Failed) plus a 'Delivery Volume' chart, a 'Provider Health' list, and a 'Channel Breakdown' — each populated or a valid empty state (zeros acceptable)"
      ]
    },
    {
      "name": "comm-runs",
      "instruction": "bulk runs summary + timeline + refresh",
      "visualCriteria": [
        "The Bulk Runs view renders a summary row (Active Runs, Completed 24h, Success Rate %) and a run timeline with status badges/dots — OR a valid 'No communication runs found' empty state — and clicking Refresh reloads the view without error"
      ]
    }
  ]
}
